import subprocess
import os
import re
from flask import Flask, request, jsonify

app = Flask(__name__)

# Configuration for backup management system
BACKUP_BASE_DIR = '/var/backups/customer'
ALLOWED_EXTENSIONS = ['.tar.gz', '.zip', '.sql.gz']

def sanitize_filename(filename):
    """Basic sanitization - remove path traversal attempts"""
    # Strip leading/trailing whitespace
    filename = filename.strip()
    # Remove null bytes
    filename = filename.replace('\x00', '')
    # Only allow alphanumeric, dash, underscore, dot
    if not re.match(r'^[a-zA-Z0-9._-]+$', filename):
        return None
    return filename

@app.route('/api/backup/verify', methods=['POST'])
def verify_backup():
    """Verify backup integrity using system checksum tools"""
    data = request.get_json()
    if not data or 'filename' not in data:
        return jsonify({'error': 'filename required'}), 400

    filename = sanitize_filename(data['filename'])
    if not filename:
        return jsonify({'error': 'invalid filename'}), 400

    # Check extension
    if not any(filename.endswith(ext) for ext in ALLOWED_EXTENSIONS):
        return jsonify({'error': 'unsupported file type'}), 400

    filepath = os.path.join(BACKUP_BASE_DIR, filename)

    if not os.path.exists(filepath):
        return jsonify({'error': 'file not found'}), 404

    # Get checksum algorithm from request, default to sha256
    algorithm = data.get('algorithm', 'sha256')

    # Build command to compute checksum
    cmd = f"{algorithm}sum {filepath}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=30
        )
        if result.returncode == 0:
            checksum = result.stdout.split()[0]
            return jsonify({'filename': filename, 'checksum': checksum, 'algorithm': algorithm})
        else:
            return jsonify({'error': 'checksum computation failed', 'details': result.stderr}), 500
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'timeout'}), 504

@app.route('/api/backup/list', methods=['GET'])
def list_backups():
    """List available backups"""
    try:
        files = os.listdir(BACKUP_BASE_DIR)
        backups = [f for f in files if any(f.endswith(ext) for ext in ALLOWED_EXTENSIONS)]
        return jsonify({'backups': backups})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/backup/schedule', methods=['POST'])
def schedule_backup():
    """Schedule a new backup job"""
    data = request.get_json()
    if not data or 'database' not in data:
        return jsonify({'error': 'database name required'}), 400

    db_name = data['database']
    # Validate database name
    if not re.match(r'^[a-zA-Z][a-zA-Z0-9_]{0,63}$', db_name):
        return jsonify({'error': 'invalid database name'}), 400

    # Schedule via cron (simplified)
    output_file = os.path.join(BACKUP_BASE_DIR, f"{db_name}_$(date +%Y%m%d).sql.gz")
    cron_entry = f"0 2 * * * pg_dump {db_name} | gzip > {output_file}"

    return jsonify({'scheduled': True, 'cron': cron_entry})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
